(function () {
'use strict';
document.addEventListener('DOMContentLoaded', function () {
var reducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
if (!reducedMotion && window.matchMedia('(pointer: fine)').matches) initCursor();
if (!reducedMotion) initMagnetic();
if (!reducedMotion) initTilt();
initReveals();
initCountUp(reducedMotion);
initNavScroll();
});
function initCursor() {
var dot = document.createElement('div');
var ring = document.createElement('div');
dot.className = 'cgp-cursor-dot';
ring.className = 'cgp-cursor-ring';
document.body.appendChild(dot);
document.body.appendChild(ring);
var x = -100, y = -100, rx = -100, ry = -100;
document.addEventListener('mousemove', function (e) {
x = e.clientX; y = e.clientY;
}, { passive: true });
var HOVER = 'a, button, [data-cursor]';
document.addEventListener('mouseover', function (e) {
if (e.target.closest(HOVER)) ring.classList.add('cgp-cursor-ring-grow');
}, { passive: true });
document.addEventListener('mouseout', function (e) {
var to = e.relatedTarget;
if (!to || !to.closest || !to.closest(HOVER)) ring.classList.remove('cgp-cursor-ring-grow');
}, { passive: true });
(function loop() {
rx += (x - rx) * 0.2;
ry += (y - ry) * 0.2;
dot.style.setProperty('--mx', x + 'px');
dot.style.setProperty('--my', y + 'px');
ring.style.setProperty('--mx', rx + 'px');
ring.style.setProperty('--my', ry + 'px');
requestAnimationFrame(loop);
})();
}
function initMagnetic() {
var MAX = 6;
document.querySelectorAll('[data-magnetic]').forEach(function (el) {
el.addEventListener('mousemove', function (e) {
var rect = el.getBoundingClientRect();
var hw = rect.width / 2, hh = rect.height / 2;
el.style.setProperty('--mx', clamp((e.clientX - rect.left - hw) / hw * MAX, MAX) + 'px');
el.style.setProperty('--my', clamp((e.clientY - rect.top - hh) / hh * MAX, MAX) + 'px');
}, { passive: true });
el.addEventListener('mouseleave', function () {
el.style.setProperty('--mx', '0px');
el.style.setProperty('--my', '0px');
});
});
}
function initTilt() {
var MAX = 6;
document.querySelectorAll('[data-tilt]').forEach(function (el) {
el.addEventListener('mousemove', function (e) {
var rect = el.getBoundingClientRect();
var px = (e.clientX - rect.left) / rect.width;
var py = (e.clientY - rect.top) / rect.height;
el.style.setProperty('--tilt-x', ((0.5 - py) * 2 * MAX) + 'deg');
el.style.setProperty('--tilt-y', ((px - 0.5) * 2 * MAX) + 'deg');
}, { passive: true });
el.addEventListener('mouseleave', function () {
el.style.setProperty('--tilt-x', '0deg');
el.style.setProperty('--tilt-y', '0deg');
});
});
}
function initReveals() {
var items = document.querySelectorAll('.cgp-reveal');
if (!items.length || !('IntersectionObserver' in window)) return;
var io = new IntersectionObserver(function (entries) {
entries.forEach(function (entry) {
if (entry.isIntersecting) {
entry.target.classList.add('cgp-reveal-visible');
io.unobserve(entry.target);
}
});
}, OPTS);
items.forEach(function (el) { io.observe(el); });
}
function initCountUp(reducedMotion) {
var items = document.querySelectorAll('[data-count]');
if (!items.length || !('IntersectionObserver' in window)) return;
function animate(el, target, suffix) {
var start = null;
function ease(t) {
return t === 1 ? 1 : 1 - Math.pow(2, -10 * t);
}
function step(ts) {
if (start === null) start = ts;
var t = Math.min((ts - start) / 1200, 1);
el.textContent = Math.round(ease(t) * target) + suffix;
if (t < 1) requestAnimationFrame(step);
}
requestAnimationFrame(step);
}
var io = new IntersectionObserver(function (entries) {
entries.forEach(function (entry) {
if (!entry.isIntersecting) return;
var el = entry.target;
var m = String(el.dataset.count).match(/^([\d.]+)(.*)$/);
var target = m ? parseFloat(m[1]) : 0;
var suffix = m ? m[2] : '';
if (reducedMotion) el.textContent = target + suffix;
else animate(el, target, suffix);
io.unobserve(el);
});
}, OPTS);
items.forEach(function (el) { io.observe(el); });
}
function initNavScroll() {
var nav = document.querySelector('[data-nav-island]');
if (!nav) return;
var ticking = false;
function update() {
nav.classList.toggle('cgp-nav-scrolled', window.scrollY > 50);
ticking = false;
}
window.addEventListener('scroll', function () {
if (!ticking) ticking = requestAnimationFrame(update);
}, { passive: true });
update();
}
var OPTS = { threshold: 0.15, rootMargin: '0px 0px -10% 0px' };
function clamp(v, max) {
return Math.max(-max, Math.min(max, v));
}
})();
document.addEventListener('alpine:init', function () {
Alpine.data('cgpShowcase', function () {
return {
activeNode: 0,
swapping: false,
paused: false,
timer: null,
nodes: [
{ id: '// NODE 01 : COOLANT LOOP', title: 'Vivid Liquid Cooling', text: 'The vibrant cyan coolant courses through meticulously hand-bent hardline tubing. We prioritize flow rate and aesthetic routing to create a mesmerizing visual centerpiece.' },
{ id: '// NODE 02 : HARDWARE FITTINGS', title: 'Precision Metallic Fittings', text: 'Notice the pristine silver and black compression fittings. Each joint is mechanically secured to prevent leaks, creating sharp, industrial right angles that contrast the circular case.' },
{ id: '// NODE 03 : MOTHERBOARD & GPU', title: 'ROG Elite Hardware', text: 'Built on an Asus ROG foundation. The motherboard and vertically mounted flagship GPU are seamlessly integrated into the water loop with custom CNC-milled acrylic blocks.' },
{ id: '// NODE 04 : THE CHASSIS', title: 'Gamemax Hotwheel', text: 'An unconventional, gravity-defying circular chassis. The open-air frame design combined with dual high-static pressure fans at the base ensures ambient air continuously feeds the radiators.' }
],
init() {
if (!window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
this.startTimer();
}
},
destroy() {
clearInterval(this.timer);
},
startTimer() {
clearInterval(this.timer);
this.timer = setInterval(() => {
if (!this.paused) this.selectNode((this.activeNode + 1) % this.nodes.length);
}, 4000);
},
selectNode(i) {
if (i === this.activeNode) return;
this.swapping = true;
this.startTimer();
setTimeout(() => { this.activeNode = i; this.swapping = false; }, 300);
}
};
});
Alpine.data('cgpShop', function () {
return {
active: 1,
step(dir) {
const s = this.$refs.slider;
const cards = s.querySelectorAll('a');
if (!cards.length) return;
const stepW = cards[0].offsetWidth + 24;
const max = s.scrollWidth - s.clientWidth;
const target = Math.max(0, Math.min(max, s.scrollLeft + dir * stepW));
s.scrollTo({ left: target, behavior: 'smooth' });
},
onScroll() {
const s = this.$refs.slider;
const cards = s.querySelectorAll('a');
if (!cards.length) return;
const sRect = s.getBoundingClientRect();
const center = sRect.left + sRect.width / 2;
let best = 0, bestDist = Infinity;
cards.forEach((c, i) => {
const r = c.getBoundingClientRect();
const cardCenter = r.left + r.width / 2;
const dist = Math.abs(cardCenter - center);
if (dist < bestDist) { bestDist = dist; best = i; }
});
this.active = best;
}
};
});
});